    # ========================================================

    def collect_load_balancers(
        self,
        clients,
        region,
        compartment
    ):

        result = []

        # Classic Load Balancers
        try:

            lbs = self.get_all(
                clients["lb"].list_load_balancers,
                compartment_id=compartment["id"],
                # Some OCI SDK/API versions default list calls to a
                # reduced "simple" view, which can leave fields like
                # lifecycle_state, shape, and IP addresses empty even
                # though the load balancer itself is healthy. Requesting
                # "full" detail explicitly avoids that.
                detail="full"
            )

            for lb in lbs:

                result.append({
                    "resource_type":
                        "Load Balancer",
                    "lb_type": "Classic",
                    "region": region,
                    "compartment":
                        compartment["path"],
                    "name": get_name(lb),
                    "id": lb.id,
                    "state": lifecycle(lb),
                    "shape": safe(
                        getattr(
                            lb,
                            "shape_name",
                            None
                        ),
                        "N/A"
                    ),
                    "ip_addresses": [
                        safe(
                            getattr(
                                ip,
                                "ip_address",
                                None
                            )
                        )
                        for ip in
                        safe(
                            getattr(
                                lb,
                                "ip_addresses",
                                []
                            ),
                            []
                        )
                    ]
                })

        except Exception as exc:

            self.record_error(
                "Load Balancer",
                region,
                compartment["path"],
                exc
            )

        # Network Load Balancers -- a separate OCI service/API from
        # classic load balancers. Skipping this used to mean any NLBs
        # in the tenancy were simply invisible to this report, not
        # merely showing blank fields.
        try:

            nlbs = self.get_all(
                clients["nlb"].list_network_load_balancers,
                compartment_id=compartment["id"]
            )

            for nlb in nlbs:

                result.append({
                    "resource_type":
                        "Load Balancer",
                    "lb_type": "Network",
                    "region": region,
                    "compartment":
                        compartment["path"],
                    "name": get_name(nlb),
                    "id": nlb.id,
                    "state": lifecycle(nlb),
                    "shape": "Flexible (NLB)",
                    "ip_addresses": [
                        safe(
                            getattr(
                                ip,
                                "ip_address",
                                None
                            )
                        )
                        for ip in
                        safe(
                            getattr(
                                nlb,
                                "ip_addresses",
                                []
                            ),
                            []
                        )
                    ]
                })

        except Exception as exc:

            self.record_error(
                "Network Load Balancer",
                region,
                compartment["path"],
                exc
            )

        return result


    # ========================================================
