def generate_html(data, filename):

    summary = data["summary"]

    for key, default in {
        "high_cpu": 0,
        "high_memory": 0,
        "high_disk": 0,
        "volumes_without_backup_policy": 0,
        "total_buckets": 0,
        "total_bucket_size_gb": 0,
        "total_bucket_objects": 0,
        "os_family_counts": {
            "Linux": 0, "Windows": 0, "Other / Custom": 0
        },
        "total_ocpus": 0,
        "total_memory_gb": 0,
        "total_boot_storage_tb": 0,
        "total_block_storage_tb": 0,
        "total_db_systems": 0,
        "total_autonomous_db": 0,
        "total_db_ocpus": 0,
        "total_db_memory_gb": 0,
        "total_db_storage_tb": 0,
        "total_file_systems": 0,
        "total_file_storage_tb": 0,
        "replicas": 0,
        "faulty_replicas": 0,
        "total_replica_storage_tb": 0,
        "total_vms": 0,
        "total_volumes": 0,
        "total_backups": 0,
        "total_block_backup_storage_tb": 0,
        "total_boot_backup_storage_tb": 0,
        "total_backup_storage_tb": 0,
        "total_network_resources": 0,
        "total_vnics": 0,
        "total_vcns": 0,
        "total_subnets": 0,
        "total_load_balancers": 0,
        "total_gateways": 0,
        "iam_groups": 0,
        "total_announcements": 0,
        "cloud_guard_status": "NOT COLLECTED",
        "cloud_guard_targets": 0,
        "cloud_guard_problems": 0,
        "cost_total": 0,
        "cost_currency": "USD",
        "cost_status": "NOT COLLECTED",
        "cost_period_days": 0,
        "cost_previous_total": 0,
        "cost_change": 0,
        "cost_change_pct": None,
        "cost_avg_daily": 0,
        "cost_monthly_runrate": 0,
        "cost_top_service": "N/A",
        "cost_top_service_amount": 0,
        "cost_top_service_pct": 0,
        "cost_top_increase_service": "N/A",
        "cost_top_increase_amount": 0,
        "cost_highest_day": "N/A",
        "cost_highest_day_amount": 0,
        "cost_lowest_day": "N/A",
        "cost_lowest_day_amount": 0,
        "cost_new_resources_count": 0,
        "cost_new_resources_amount": 0,
        "cost_warnings": []
    }.items():
        summary.setdefault(key, default)

    metadata = data["metadata"]
    recommendations = data.get("recommendations", [])
    cost_points = data.get("cost", {}).get("daily", [])
    cost_currency = data.get("cost", {}).get("currency", "USD")
    symbol = _currency_symbol(cost_currency)

    def money(amount):
        return f"{symbol}{amount:,.2f}"

    # ------------------------------------------------ cross-references
    by_section = {}

    for index, rec in enumerate(recommendations, start=1):
        by_section.setdefault(rec.get("section"), []).append((index, rec))

    def findings(section_id):
        items = by_section.get(section_id)
        if not items:
            return ""
        links = "".join(
            f'<a href="#rec-{index}">'
            + _pill(
                rec["severity"].upper(),
                {"high": "bad", "medium": "warn"}.get(rec["severity"], "info")
            )
            + f'<span>{html_escape(rec["title"])}</span></a>'
            for index, rec in items
        )
        state = " open" if len(items) <= FINDINGS_OPEN_LIMIT else ""
        return (
            f'<details class="findings"{state}><summary class="findings-title">'
            f"Findings in this section ({len(items)})</summary>{links}</details>"
        )

    def nav_badge(section_id):
        items = by_section.get(section_id)
        if not items:
            return ""
        worst = min(
            (rec["severity"] for _, rec in items),
            key=["high", "medium", "low"].index
        )
        return f'<span class="toc-count {worst}">{len(items)}</span>'

    ctx = {
        "money": money,
        "symbol": symbol,
        "findings": findings,
        "health": compute_health_scores(recommendations),
        "severity_counts": {
            severity: len([
                r for r in recommendations if r.get("severity") == severity
            ])
            for severity in ("high", "medium", "low")
        },
        "total_savings": round(sum(
            r.get("estimated_savings") or 0 for r in recommendations
        ), 2),
        "cost_chart": build_stacked_cost_chart_html(
            cost_points, cost_currency
        ),
        "trend_chart": build_cost_trend_line_html(
            cost_points, cost_currency
        ),
    }

    renderers = {
        "summary": _render_summary,
        "recommendations": _render_recommendations,
        "billing": _render_billing,
        "compute-instances": _render_compute,
        "volume-policies": _render_volumes,
        "database": _render_database,
        "object-storage": _render_object_storage,
        "file-storage": _render_file_storage,
        "replication": _render_replication,
        "networking": _render_networking,
        "iam-security": _render_iam,
        "alarms": _render_alarms,
        "announcements": _render_announcements,
        "region-overview": _render_regions,
        "compartments": _render_compartments,
        "collection-errors": _render_errors,
    }

    sections_html = "\n".join(
        renderers[section_id](data, ctx)
        for section_id, _, _ in REPORT_SECTIONS
    )

    nav_parts = []
    current_group = None

    for section_id, label, group in REPORT_SECTIONS:
        if group != current_group:
            current_group = group
            nav_parts.append(
                f'<div class="toc-group">{html_escape(group)}</div>'
            )
        badge = (
            f'<span class="toc-count low">{len(recommendations)}</span>'
            if section_id == "recommendations" and recommendations
            else nav_badge(section_id)
        )
        nav_parts.append(
            f'<a href="#{section_id}"><span>{html_escape(label)}</span>{badge}</a>'
        )

    customer = html_escape(metadata["customer_name"])
    report_name = html_escape(metadata["report_name"])

    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{report_name}</title>
<style>{REPORT_CSS}</style>
</head>
<body>

<header class="header">
<div class="header-inner">
<div>
<img class="logo" src="data:image/png;base64,{ZAINTECH_LOGO_BASE64}" alt="ZainTECH">
<div class="eyebrow">Managed Services &middot; Cloud Health Report</div>
<h1>{report_name}</h1>
</div>
<dl class="header-meta">
<dt>Prepared for</dt><dd>{customer}</dd>
<dt>Period</dt><dd>{html_escape(metadata.get("period_start"))} to {html_escape(metadata.get("period_end"))}</dd>
<dt>Generated</dt><dd>{_short_timestamp(metadata["generated_at"])}</dd>
</dl>
</div>
<div class="confidential">Confidential. Prepared exclusively for {customer} by ZainTECH Managed Services.</div>
</header>

<div class="layout">
<nav class="toc" aria-label="Report sections">
{"".join(nav_parts)}
</nav>
<main class="content">
{sections_html}
</main>
</div>

<footer class="footer">
&copy; {html_escape(metadata["generated_at"][:4])} ZainTECH. This report is confidential and intended solely for {customer}. Please do not forward without authorization.
</footer>

<script>{REPORT_JS}</script>
</body>
</html>
"""

    with open(
        filename,
        "w",
        encoding="utf-8"
    ) as file:

        file.write(html)


# ============================================================
# JSON
# ============================================================

def generate_json(data, filename):

    with open(
        filename,
        "w",
        encoding="utf-8"
    ) as file:

        json.dump(
            data,
            file,
            indent=4,
            default=str
        )


# ============================================================
# MAIN
# ============================================================

def run_profile(args, profile, multiple_profiles=False):

    try:

        checker = OCIHealthCheck(
            profile=profile,
            region=args.region,
            announcement_days=args.announcement_days,
            backup_max_age_days=args.backup_age,
            config_file=args.config_file,
            max_workers=args.max_workers,
            customer_name=args.customer_name,
            cost_analysis_days=args.cost_days,
            utilization_days=args.utilization_days
        )

        data = checker.collect()

        date_string = datetime.datetime.now().strftime(
            "%Y-%m-%d"
        )

        # Always include the profile name in the output filename (not
        # just when scanning multiple profiles in one run), so reports
        # for different tenancies/customers never collide or get
        # overwritten, and it's obvious which tenancy a file belongs to
        # at a glance.
        prefix = f"OCI_Health_Report_{profile}"

        html_file = os.path.join(
            args.output,
            f"{prefix}_{date_string}.html"
        )

        json_file = os.path.join(
            args.output,
            f"{prefix}_{date_string}.json"
        )

        generate_html(data, html_file)
        generate_json(data, json_file)

        summary = data["summary"]

        print("")
        print("=" * 70)
        print(f"OCI HEALTH CHECK SUMMARY ({profile})")
        print("=" * 70)

        for label, value in [
            ("Overall Status", summary["overall_status"]),
            ("IAM Users", summary["iam_users"]),
            (
                "Cloud Guard",
                f"{summary['cloud_guard_status']} "
                f"(Problems: {summary['cloud_guard_problems']})"
            ),
            ("Running VMs", summary["running_vms"]),
            ("Stopped VMs", summary["stopped_vms"]),
            ("Backup Issues", summary["backup_issues"]),
            ("Firing Alarms", summary["firing_alarms"]),
            ("OCI Announcements", summary["oci_announcements"]),
            ("Regions Scanned", summary["regions_scanned"]),
            ("Compartments", summary["compartments"]),
            ("Resources", summary["total_resources"]),
            ("Collection Errors", summary["collection_errors"]),
            (
                f"Cost ({summary['cost_period_days']} days)",
                f"{summary['cost_currency']} {summary['cost_total']:,.2f}"
                + (
                    f" ({summary['cost_change_pct']:+.1f}% vs previous)"
                    if summary.get("cost_change_pct") is not None
                    else ""
                )
            ),
            (
                "Recommendations",
                f"{summary['recommendations']} "
                f"({summary['high_priority_recommendations']} high)"
            )
        ]:
            print(f"{label:<20}: {value}")

        high = [
            r for r in data.get("recommendations", [])
            if r["severity"] == "high"
        ]
        if high:
            print("")
            print("High-priority recommendations:")
            for rec in high:
                print(f"  - [{rec['category']}] {rec['title']}")

        print("")
        print(f"HTML Report : {html_file}")
        print(f"JSON Report : {json_file}")
        print("=" * 70)

        return True

    except Exception as exc:

        print("")
        print(f"[FATAL ERROR] Profile {profile}")
        print(str(exc))
        print("")
        traceback.print_exc()
        return False


def main():

    parser = argparse.ArgumentParser(
        description=
        "OCI Weekly Health Check"
    )

    parser.add_argument(
        "--profile",
        default=DEFAULT_OCI_PROFILE,
        help="OCI config profile, or a comma-separated list of profiles"
    )

    parser.add_argument(
        "--profiles",
        default=None,
        help="Comma-separated OCI config profiles to scan"
    )

    parser.add_argument(
        "--config-file",
        default=os.environ.get(
            "OCI_CONFIG_FILE",
            "~/.oci/config"
        ),
        help="OCI config file path"
    )

    parser.add_argument(
        "--region",
        default=None,
        help="Only scan this OCI region"
    )

    parser.add_argument(
        "--days",
        type=int,
        default=DEFAULT_REPORT_PERIOD_DAYS,
        help=(
            "Reporting period in days for cost, utilization, "
            "announcements and new resources (default: "
            f"{DEFAULT_REPORT_PERIOD_DAYS}, i.e. weekly; max 90)"
        )
    )

    parser.add_argument(
        "--announcement-days",
        type=int,
        default=None,
        help="Override the announcement window (default: --days)"
    )

    parser.add_argument(
        "--backup-age",
        type=int,
        default=DEFAULT_BACKUP_MAX_AGE_DAYS,
        help=(
            "Flag a volume when its latest backup is older than this "
            "many days"
        )
    )

    parser.add_argument(
        "--cost-days",
        type=int,
        default=None,
        help=(
            "Override the cost analysis period (default: --days). The "
            "previous period of the same length is used for comparison"
        )
    )

    parser.add_argument(
        "--utilization-days",
        type=int,
        default=None,
        help="Override the utilization metrics window (default: --days)"
    )

    parser.add_argument(
        "--output",
        default=".",
        help="Output directory"
    )

    parser.add_argument(
        "--max-workers",
        type=int,
        default=6,
        help="Concurrent compartments per region (maximum 12)"
    )

    parser.add_argument(
        "--customer-name",
        default=None,
        help=(
            "Customer-facing name shown on the report (defaults to the "
            "OCI profile name if not set — recommended to always set this "
            "explicitly for reports sent to a customer)"
        )
    )

    args = parser.parse_args()

    if not 1 <= args.days <= 90:
        parser.error("--days must be between 1 and 90")

    for option in ("announcement_days", "cost_days", "utilization_days"):
        if getattr(args, option) is None:
            setattr(args, option, args.days)


    os.makedirs(
        args.output,
        exist_ok=True
    )


    # Both the configured default and --profile may contain multiple
    # comma-separated OCI profile names. The default can also be a Python
    # list or tuple, which is convenient when maintaining it in this file.
    # This lets the script run every default profile without requiring
    # --profiles on each invocation.
    profiles_value = args.profiles if args.profiles else args.profile
    raw_profiles = (
        profiles_value
        if isinstance(profiles_value, (list, tuple))
        else profiles_value.split(",")
    )
    profiles = [
        str(profile).strip()
        for profile in raw_profiles
        if str(profile).strip()
    ]

    if not profiles:
        parser.error("--profiles must contain at least one profile")

    successful = 0

    for profile in profiles:
        if run_profile(
            args,
            profile,
            multiple_profiles=len(profiles) > 1
        ):
            successful += 1

    if successful != len(profiles):
        sys.exit(1)


if __name__ == "__main__":
    main()